   S("III. Facteurs", table=[["Facteur", "Influence ?"], ["Profondeur", "non"], ["Quantité de liquide", "non"], ["Poids du corps", "non"], ["Volume immergé", "oui"], ["Nature du liquide", "oui"]]),
